import pytest
from isort.setuptools_commands import ISortCommand

class MockDistribution:
    def __init__(self, packages=None, py_modules=None, package_dir=None):
        self.packages = packages or []
        self.py_modules = py_modules or []
        self.package_dir = package_dir or {}

@pytest.fixture
def isort_command():
    return ISortCommand()

def test_distribution_files_with_packages(isort_command):
    isort_command.distribution = MockDistribution(
        packages=["pkg1", "pkg2"],
        package_dir={"pkg1": "src/pkg1", "pkg2": "src/pkg2"}
    )
    expected = ["src/pkg1", "src/pkg2", "setup.py"]
    assert list(isort_command.distribution_files()) == expected

def test_distribution_files_with_package_dirs_default(isort_command):
    isort_command.distribution = MockDistribution(
        packages=["pkg1"],
        package_dir={}
    )
    expected = ["pkg1", "setup.py"]
    assert list(isort_command.distribution_files()) == expected

def test_distribution_files_with_empty_packages(isort_command):
    isort_command.distribution = MockDistribution(
        packages=[],
        py_modules=["module1", "module2"]
    )
    expected = ["module1.py", "module2.py", "setup.py"]
    assert list(isort_command.distribution_files()) == expected

def test_distribution_files_with_py_modules(isort_command):
    isort_command.distribution = MockDistribution(
        py_modules=["module1", "module2"]
    )
    expected = ["module1.py", "module2.py", "setup.py"]
    assert list(isort_command.distribution_files()) == expected

def test_distribution_files_with_packages_and_py_modules(isort_command):
    isort_command.distribution = MockDistribution(
        packages=["pkg1"],
        py_modules=["module1"],
        package_dir={"pkg1": "src/pkg1"}
    )
    expected = ["src/pkg1", "module1.py", "setup.py"]
    assert list(isort_command.distribution_files()) == expected

import pytest
from isort._vendored.tomli._parser import Flags  # Adjust the import as necessary

def test_is_with_valid_key_and_flag():
    flags = Flags()
    flags._flags = {
        'level1': {
            'nested': {
                'level2': {
                    'flags': [1, 2],
                    'recursive_flags': [3]
                }
            }
        }
    }
    assert flags.is_(['level1', 'level2'], 1) is True
    assert flags.is_(['level1', 'level2'], 3) is True
    assert flags.is_(['level1', 'level2'], 4) is False

def test_is_with_missing_keys():
    flags = Flags()
    flags._flags = {
        'level1': {
            'nested': {}
        }
    }
    assert flags.is_(['level1', 'level2'], 1) is False

def test_is_with_empty_key():
    flags = Flags()
    assert flags.is_(None, 1) is False

def test_is_with_nested_flags():
    flags = Flags()
    flags._flags = {
        'level1': {
            'nested': {
                'level2': {
                    'flags': [],
                    'recursive_flags': [3]
                }
            }
        }
    }
    assert flags.is_(['level1', 'level2'], 3) is True
    assert flags.is_(['level1', 'level2'], 1) is False

def test_is_with_nonexistent_nested():
    flags = Flags()
    flags._flags = {
        'level1': {
            'nested': {
                'level2': {
                    'flags': [1],
                    'recursive_flags': []
                }
            }
        }
    }
    assert flags.is_(['level1', 'level2', 'level3'], 1) is False

import os
import pytest
from unittest.mock import patch, MagicMock
from isort.deprecated.finders import ReqsBaseFinder


@pytest.fixture
def temp_file(tmp_path):
    """Create a temporary requirements file."""
    req_file = tmp_path / "requirements.txt"
    req_file.write_text("package1\npackage2\n")
    return str(req_file)


@pytest.fixture
def temp_dir_with_requirements(tmp_path):
    """Create a temporary directory with multiple requirement files."""
    req_file_1 = tmp_path / "requirements.txt"
    req_file_2 = tmp_path / "requirements_dev.txt"
    req_file_1.write_text("package1\npackage2\n")
    req_file_2.write_text("package3\npackage4\n")
    return str(tmp_path)


@pytest.fixture
def empty_temp_dir(tmp_path):
    """Create an empty temporary directory."""
    return str(tmp_path)


@pytest.fixture
def no_requirements_dir(tmp_path):
    """Create a directory that does not contain any requirements files."""
    return str(tmp_path)


def test_get_files_with_file_path(temp_file):
    finder = ReqsBaseFinder()
    finder.path = temp_file
    files = list(finder._get_files())
    assert files == [temp_file]


def test_get_files_with_directory(temp_dir_with_requirements):
    finder = ReqsBaseFinder()
    finder.path = temp_dir_with_requirements
    files = list(finder._get_files())
    expected_files = [
        os.path.join(temp_dir_with_requirements, "requirements.txt"),
        os.path.join(temp_dir_with_requirements, "requirements_dev.txt")
    ]
    assert sorted(files) == sorted(expected_files)


def test_get_files_with_empty_directory(empty_temp_dir):
    finder = ReqsBaseFinder()
    finder.path = empty_temp_dir
    files = list(finder._get_files())
    assert files == []


def test_get_files_invalid_path():
    finder = ReqsBaseFinder()
    finder.path = "invalid_path"

    with pytest.raises(FileNotFoundError):
        list(finder._get_files())


def test_get_files_no_requirements(no_requirements_dir):
    finder = ReqsBaseFinder()
    finder.path = no_requirements_dir
    files = list(finder._get_files())
    assert files == []

import pytest
from isort.format import format_simplified

def test_format_simplified_from_import():
    assert format_simplified("from module import function") == "module.function"

def test_format_simplified_import():
    assert format_simplified("import module") == "module"

def test_format_simplified_stripper():
    assert format_simplified("   from module import function   ") == "module.function"

def test_format_simplified_empty():
    assert format_simplified("") == ""

def test_format_simplified_no_change():
    assert format_simplified("some random text") == "some random text"

import sys
import pytest
from unittest.mock import patch
from isort import format


def ask_whether_to_apply_changes_to_file(file_path: str) -> bool:
    answer = None
    while answer not in ("yes", "y", "no", "n", "quit", "q"):
        answer = input(f"Apply suggested changes to '{file_path}' [y/n/q]? ")  # nosec
        answer = answer.lower()
        if answer in ("no", "n"):
            return False
        if answer in ("quit", "q"):
            sys.exit(1)
    return True


def test_apply_changes_yes():
    with patch('builtins.input', return_value='y'):
        assert ask_whether_to_apply_changes_to_file("test_file.txt") is True


def test_apply_changes_no():
    with patch('builtins.input', return_value='n'):
        assert ask_whether_to_apply_changes_to_file("test_file.txt") is False


def test_apply_changes_quit():
    with patch('builtins.input', return_value='q'):
        with pytest.raises(SystemExit):
            ask_whether_to_apply_changes_to_file("test_file.txt")


def test_apply_changes_invalid_input_then_yes():
    with patch('builtins.input', side_effect=['invalid', 'y']):
        assert ask_whether_to_apply_changes_to_file("test_file.txt") is True


def test_apply_changes_invalid_input_then_no():
    with patch('builtins.input', side_effect=['invalid', 'n']):
        assert ask_whether_to_apply_changes_to_file("test_file.txt") is False
